// ***************
// Filename: object_tracker_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of object_tracker: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to object_tracker's logic on named ports,
//   its status comes back on input ports. Object detector / measurement:
//   bounding box, count and sums of the object pixels (luma threshold or
//   colour ranges, run widths) in a search window, per frame. Generated by
//   ip/scripts/regmap_gen.py from object_tracker_regs.json: edit the JSON and
//   regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 9, byte offsets):
//     0x000 ID          RO   "OTRK" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x004 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x008 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x00C reserved    RO   0
//     0x018 CTRL        RW   control, reset 0x0
//                       [0] EN: enable
//                       [1] POL: luma mode, 1: object darker than THRESH
//                       [2] MODE: 0 luma threshold, 1 colour ranges (Y_RANGE,
//                         CB_RANGE, CR_RANGE, SAT_MIN)
//                       [11:8] MIN_RUN: shortest run counted when RUN.MIN_W =
//                         0 (0 or 1: every pixel counts)
//                       [13:12] FEAT_A: term A: 0 the luma / colour test, 1
//                         it or the motion feature, 2 it and the motion
//                         feature, 3 the motion feature
//                       [14] TERM_B: term B on: the edge feature, in runs of
//                         RUN_B (its own blob slots)
//                       [15] SKIN_LUT: colour mode: the chroma test is the
//                         SKIN_LUT table instead of CB_RANGE / CR_RANGE /
//                         SAT_MIN (Y_RANGE still applies)
//     0x01C FRAME_SIZE  RW   frame size, reset 0x0
//                       [15:0] WIDTH: width
//                       [31:16] HEIGHT: height
//     0x020 THRESH      RW   luma threshold, reset 0x0
//     0x024 WIN_X       RW   search window columns (inclusive, taken at the
//                       frame start), reset 0x0
//                       [15:0] X0: first
//                       [31:16] X1: last
//     0x028 WIN_Y       RW   search window lines, reset 0x0
//                       [15:0] Y0: first
//                       [31:16] Y1: last
//     0x02C FRAMES      RO   frames measured
//     0x030 COUNT       RO   object pixels in the last frame (0: nothing
//                       found)
//     0x034 BOX_X       RO   object box columns of the last frame
//                       [15:0] X_MIN: min
//                       [31:16] X_MAX: max
//     0x038 BOX_Y       RO   object box lines
//                       [15:0] Y_MIN: min
//                       [31:16] Y_MAX: max
//     0x03C SUM_X       RO   sum of the object pixels' x (centroid = SUM_X /
//                       COUNT)
//     0x040 SUM_Y       RO   sum of their y
//     0x044 STATUS      RO   state
//                       [0] IN_FRAME: in a frame
//                       [1] FULL_WIN: the window of the frame being measured
//                         is the whole frame
//                       [15:8] BLOB_LOST: runs of the last frame not grouped
//                         into a blob (every slot taken; saturates at 255)
//                       [31:16] FRAMES: FRAMES[15:0]
//     0x048 RUN         RW   run widths counted (a horizontal run of object
//                       pixels is judged when it ends), reset 0x0
//                       [11:0] MIN_W: shortest run (0: CTRL.MIN_RUN)
//                       [27:16] MAX_W: longest run (0: no limit)
//     0x04C Y_RANGE     RW   colour mode: luma Y = (R + 2G + B) / 4 range,
//                       reset 0xFF00
//                       [7:0] MIN: lowest
//                       [15:8] MAX: highest
//     0x050 CB_RANGE    RW   colour mode: Cb = 128 + (B - Y) / 2 range, reset
//                       0xFF00
//                       [7:0] MIN: lowest
//                       [15:8] MAX: highest
//     0x054 CR_RANGE    RW   colour mode: Cr = 128 + (R - Y) / 2 range, reset
//                       0xFF00
//                       [7:0] MIN: lowest
//                       [15:8] MAX: highest
//     0x058 SAT_MIN     RW   colour mode: lowest saturation |Cb - 128| + |Cr
//                       - 128|, reset 0x0
//     0x05C BLOB_CFG    RW   blob grouping of the counted runs, reset 0x202
//                       [7:0] GAP: a run joins a blob within GAP columns of
//                         its box
//                       [15:8] GAP_Y: and at most GAP_Y + 1 lines below its
//                         last line
//                       [31:16] KEEP: fewest pixels of a blob kept (a closed
//                         smaller blob frees its slot; reported only from
//                         KEEP pixels)
//     0x060 + 4 i SCRATCH [28] RW   CPU scratch words (the firmware's
//                       tracking state of this detector's objects), reset 0x0
//     0x0D0 RUN_B       RW   term B run widths counted (judged when a run
//                       ends, by its whole length), reset 0x0
//                       [11:0] MIN_W: shortest run (0: 1)
//                       [27:16] MAX_W: longest run (0: no limit)
//     0x100 + 4 i BLOB_X [8]  RO   blob i columns at the end of the last
//                       frame (BLOB_N = 0: none)
//                       [15:0] X_MIN: min
//                       [31:16] X_MAX: max
//     0x120 + 4 i BLOB_Y [8]  RO   blob i lines
//                       [15:0] Y_MIN: min
//                       [31:16] Y_MAX: max
//     0x140 + 4 i BLOB_N [8]  RO   blob i pixels (0: no blob)
//     0x160 + 4 i SKIN_LUT [32] RW   learned skin table (python-
//                       prototype/train_skin.py): word i = (Cr - 112) >> 1,
//                       bit j = (Cb - 96) >> 1 (Cb 96..159, Cr 112..175); 1 =
//                       skin, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-21
module object_tracker_regs (
  input  logic                 clk,             // clock
  input  logic                 rst_n,           // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 9
  axil_if.slave s_axil,
  // r: object_tracker_regs_if.regs (src/include/object_tracker_regs_if.sv) {ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr frame_size_o=cfg_frame_size frame_size_wr_o=cfg_frame_size_wr thresh_o=cfg_thresh thresh_wr_o=cfg_thresh_wr win_x_o=cfg_win_x win_x_wr_o=cfg_win_x_wr win_y_o=cfg_win_y win_y_wr_o=cfg_win_y_wr frames_i=sts_frames count_i=sts_count box_x_i=sts_box_x box_y_i=sts_box_y sum_x_i=sts_sum_x sum_y_i=sts_sum_y status_i=sts_status run_o=cfg_run run_wr_o=cfg_run_wr y_range_o=cfg_y_range y_range_wr_o=cfg_y_range_wr cb_range_o=cfg_cb_range cb_range_wr_o=cfg_cb_range_wr cr_range_o=cfg_cr_range cr_range_wr_o=cfg_cr_range_wr sat_min_o=cfg_sat_min sat_min_wr_o=cfg_sat_min_wr blob_cfg_o=cfg_blob_cfg blob_cfg_wr_o=cfg_blob_cfg_wr scratch_o=cfg_scratch scratch_wr_o=cfg_scratch_wr run_b_o=cfg_run_b run_b_wr_o=cfg_run_b_wr blob_x_i=sts_blob_x blob_y_i=sts_blob_y blob_n_i=sts_blob_n skin_lut_o=cfg_skin_lut skin_lut_wr_o=cfg_skin_lut_wr}
  object_tracker_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [32-1:0] ctrl_o;
  logic ctrl_wr_o;
  logic [32-1:0] frame_size_o;
  logic frame_size_wr_o;
  logic [8-1:0] thresh_o;
  logic thresh_wr_o;
  logic [32-1:0] win_x_o;
  logic win_x_wr_o;
  logic [32-1:0] win_y_o;
  logic win_y_wr_o;
  logic [32-1:0] frames_i;
  logic [32-1:0] count_i;
  logic [32-1:0] box_x_i;
  logic [32-1:0] box_y_i;
  logic [32-1:0] sum_x_i;
  logic [32-1:0] sum_y_i;
  logic [32-1:0] status_i;
  logic [32-1:0] run_o;
  logic run_wr_o;
  logic [16-1:0] y_range_o;
  logic y_range_wr_o;
  logic [16-1:0] cb_range_o;
  logic cb_range_wr_o;
  logic [16-1:0] cr_range_o;
  logic cr_range_wr_o;
  logic [8-1:0] sat_min_o;
  logic sat_min_wr_o;
  logic [32-1:0] blob_cfg_o;
  logic blob_cfg_wr_o;
  logic [(28)*(32)-1:0] scratch_o;
  logic [28-1:0] scratch_wr_o;
  logic [32-1:0] run_b_o;
  logic run_b_wr_o;
  logic [(8)*(32)-1:0] blob_x_i;
  logic [(8)*(32)-1:0] blob_y_i;
  logic [(8)*(32)-1:0] blob_n_i;
  logic [(32)*(32)-1:0] skin_lut_o;
  logic [32-1:0] skin_lut_wr_o;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign r.cfg_frame_size = frame_size_o;
  assign r.cfg_frame_size_wr = frame_size_wr_o;
  assign r.cfg_thresh = thresh_o;
  assign r.cfg_thresh_wr = thresh_wr_o;
  assign r.cfg_win_x = win_x_o;
  assign r.cfg_win_x_wr = win_x_wr_o;
  assign r.cfg_win_y = win_y_o;
  assign r.cfg_win_y_wr = win_y_wr_o;
  assign frames_i = r.sts_frames;
  assign count_i = r.sts_count;
  assign box_x_i = r.sts_box_x;
  assign box_y_i = r.sts_box_y;
  assign sum_x_i = r.sts_sum_x;
  assign sum_y_i = r.sts_sum_y;
  assign status_i = r.sts_status;
  assign r.cfg_run = run_o;
  assign r.cfg_run_wr = run_wr_o;
  assign r.cfg_y_range = y_range_o;
  assign r.cfg_y_range_wr = y_range_wr_o;
  assign r.cfg_cb_range = cb_range_o;
  assign r.cfg_cb_range_wr = cb_range_wr_o;
  assign r.cfg_cr_range = cr_range_o;
  assign r.cfg_cr_range_wr = cr_range_wr_o;
  assign r.cfg_sat_min = sat_min_o;
  assign r.cfg_sat_min_wr = sat_min_wr_o;
  assign r.cfg_blob_cfg = blob_cfg_o;
  assign r.cfg_blob_cfg_wr = blob_cfg_wr_o;
  assign r.cfg_scratch = scratch_o;
  assign r.cfg_scratch_wr = scratch_wr_o;
  assign r.cfg_run_b = run_b_o;
  assign r.cfg_run_b_wr = run_b_wr_o;
  assign blob_x_i = r.sts_blob_x;
  assign blob_y_i = r.sts_blob_y;
  assign blob_n_i = r.sts_blob_n;
  assign r.cfg_skin_lut = skin_lut_o;
  assign r.cfg_skin_lut_wr = skin_lut_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "OTRK";
  localparam logic [31:0] IP_VERSION = "1.00";
  localparam logic [31:0] IP_DATE    = 32'h10132026;   // mm/dd/yyyy, BCD
  localparam logic [8:0] A_ID = 9'h0, A_VERSION = 9'h4, A_DATE = 9'h8;
  localparam logic [8:0] A_CTRL = 9'h18;
  localparam logic [8:0] A_FRAME_SIZE = 9'h1C;
  localparam logic [8:0] A_THRESH = 9'h20;
  localparam logic [8:0] A_WIN_X = 9'h24;
  localparam logic [8:0] A_WIN_Y = 9'h28;
  localparam logic [8:0] A_FRAMES = 9'h2C;
  localparam logic [8:0] A_COUNT = 9'h30;
  localparam logic [8:0] A_BOX_X = 9'h34;
  localparam logic [8:0] A_BOX_Y = 9'h38;
  localparam logic [8:0] A_SUM_X = 9'h3C;
  localparam logic [8:0] A_SUM_Y = 9'h40;
  localparam logic [8:0] A_STATUS = 9'h44;
  localparam logic [8:0] A_RUN = 9'h48;
  localparam logic [8:0] A_Y_RANGE = 9'h4C;
  localparam logic [8:0] A_CB_RANGE = 9'h50;
  localparam logic [8:0] A_CR_RANGE = 9'h54;
  localparam logic [8:0] A_SAT_MIN = 9'h58;
  localparam logic [8:0] A_BLOB_CFG = 9'h5C;
  localparam logic [8:0] A_SCRATCH = 9'h60;   // + 4 i, i < 28
  localparam logic [8:0] A_RUN_B = 9'hD0;
  localparam logic [8:0] A_BLOB_X = 9'h100;   // + 4 i, i < 8
  localparam logic [8:0] A_BLOB_Y = 9'h120;   // + 4 i, i < 8
  localparam logic [8:0] A_BLOB_N = 9'h140;   // + 4 i, i < 8
  localparam logic [8:0] A_SKIN_LUT = 9'h160;   // + 4 i, i < 32
  localparam int MAP_WORDS = 120;

  logic             wr_en, rd_en, wr_err_q;
  logic [8:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(9)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(9),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [8:0] wa = {wr_addr[8:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] frame_size_q;
  logic [31:0] thresh_q;
  logic [31:0] win_x_q;
  logic [31:0] win_y_q;
  logic [31:0] run_q;
  logic [31:0] y_range_q;
  logic [31:0] cb_range_q;
  logic [31:0] cr_range_q;
  logic [31:0] sat_min_q;
  logic [31:0] blob_cfg_q;
  logic [31:0] scratch_q [28];
  logic [31:0] run_b_q;
  logic [31:0] skin_lut_q [32];
  logic ro_blob_x;   // a write to an element of BLOB_X
  always_comb begin
    ro_blob_x = 1'b0;
    for (int i = 0; i < 8; i++) if (wa == A_BLOB_X + 9'(4 * i)) ro_blob_x = 1'b1;
  end
  logic ro_blob_y;   // a write to an element of BLOB_Y
  always_comb begin
    ro_blob_y = 1'b0;
    for (int i = 0; i < 8; i++) if (wa == A_BLOB_Y + 9'(4 * i)) ro_blob_y = 1'b1;
  end
  logic ro_blob_n;   // a write to an element of BLOB_N
  always_comb begin
    ro_blob_n = 1'b0;
    for (int i = 0; i < 8; i++) if (wa == A_BLOB_N + 9'(4 * i)) ro_blob_n = 1'b1;
  end
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      ctrl_q <= 32'h0;
      ctrl_wr_o <= 1'b0;
      frame_size_q <= 32'h0;
      frame_size_wr_o <= 1'b0;
      thresh_q <= 32'h0;
      thresh_wr_o <= 1'b0;
      win_x_q <= 32'h0;
      win_x_wr_o <= 1'b0;
      win_y_q <= 32'h0;
      win_y_wr_o <= 1'b0;
      run_q <= 32'h0;
      run_wr_o <= 1'b0;
      y_range_q <= 32'hFF00;
      y_range_wr_o <= 1'b0;
      cb_range_q <= 32'hFF00;
      cb_range_wr_o <= 1'b0;
      cr_range_q <= 32'hFF00;
      cr_range_wr_o <= 1'b0;
      sat_min_q <= 32'h0;
      sat_min_wr_o <= 1'b0;
      blob_cfg_q <= 32'h202;
      blob_cfg_wr_o <= 1'b0;
      for (int i = 0; i < 28; i++) scratch_q[i] <= 32'h0;
      scratch_wr_o <= '0;
      run_b_q <= 32'h0;
      run_b_wr_o <= 1'b0;
      for (int i = 0; i < 32; i++) skin_lut_q[i] <= 32'h0;
      skin_lut_wr_o <= '0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_FRAMES || wa == A_COUNT || wa == A_BOX_X || wa == A_BOX_Y || wa == A_SUM_X || wa == A_SUM_Y || wa == A_STATUS || ro_blob_x || ro_blob_y || ro_blob_n);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_size_wr_o <= wr_en && wa == A_FRAME_SIZE;
        if (wr_en && wa == A_FRAME_SIZE) frame_size_q <= (frame_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        thresh_wr_o <= wr_en && wa == A_THRESH;
        if (wr_en && wa == A_THRESH) thresh_q <= (thresh_q & ~wmask) | (wr_data & wmask);
      end
      begin
        win_x_wr_o <= wr_en && wa == A_WIN_X;
        if (wr_en && wa == A_WIN_X) win_x_q <= (win_x_q & ~wmask) | (wr_data & wmask);
      end
      begin
        win_y_wr_o <= wr_en && wa == A_WIN_Y;
        if (wr_en && wa == A_WIN_Y) win_y_q <= (win_y_q & ~wmask) | (wr_data & wmask);
      end
      begin
        run_wr_o <= wr_en && wa == A_RUN;
        if (wr_en && wa == A_RUN) run_q <= (run_q & ~wmask) | (wr_data & wmask);
      end
      begin
        y_range_wr_o <= wr_en && wa == A_Y_RANGE;
        if (wr_en && wa == A_Y_RANGE) y_range_q <= (y_range_q & ~wmask) | (wr_data & wmask);
      end
      begin
        cb_range_wr_o <= wr_en && wa == A_CB_RANGE;
        if (wr_en && wa == A_CB_RANGE) cb_range_q <= (cb_range_q & ~wmask) | (wr_data & wmask);
      end
      begin
        cr_range_wr_o <= wr_en && wa == A_CR_RANGE;
        if (wr_en && wa == A_CR_RANGE) cr_range_q <= (cr_range_q & ~wmask) | (wr_data & wmask);
      end
      begin
        sat_min_wr_o <= wr_en && wa == A_SAT_MIN;
        if (wr_en && wa == A_SAT_MIN) sat_min_q <= (sat_min_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blob_cfg_wr_o <= wr_en && wa == A_BLOB_CFG;
        if (wr_en && wa == A_BLOB_CFG) blob_cfg_q <= (blob_cfg_q & ~wmask) | (wr_data & wmask);
      end
      for (int i = 0; i < 28; i++) begin
        scratch_wr_o[i] <= wr_en && wa == A_SCRATCH + 9'(4 * i);
        if (wr_en && wa == A_SCRATCH + 9'(4 * i)) scratch_q[i] <= (scratch_q[i] & ~wmask) | (wr_data & wmask);
      end
      begin
        run_b_wr_o <= wr_en && wa == A_RUN_B;
        if (wr_en && wa == A_RUN_B) run_b_q <= (run_b_q & ~wmask) | (wr_data & wmask);
      end
      for (int i = 0; i < 32; i++) begin
        skin_lut_wr_o[i] <= wr_en && wa == A_SKIN_LUT + 9'(4 * i);
        if (wr_en && wa == A_SKIN_LUT + 9'(4 * i)) skin_lut_q[i] <= (skin_lut_q[i] & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[32-1:0];
  assign frame_size_o = frame_size_q[32-1:0];
  assign thresh_o = thresh_q[8-1:0];
  assign win_x_o = win_x_q[32-1:0];
  assign win_y_o = win_y_q[32-1:0];
  assign run_o = run_q[32-1:0];
  assign y_range_o = y_range_q[16-1:0];
  assign cb_range_o = cb_range_q[16-1:0];
  assign cr_range_o = cr_range_q[16-1:0];
  assign sat_min_o = sat_min_q[8-1:0];
  assign blob_cfg_o = blob_cfg_q[32-1:0];
  always_comb for (int i = 0; i < 28; i++) scratch_o[i*(32) +: 32] = scratch_q[i][32-1:0];
  assign run_b_o = run_b_q[32-1:0];
  always_comb for (int i = 0; i < 32; i++) skin_lut_o[i*(32) +: 32] = skin_lut_q[i][32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[8:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = 32'(ctrl_q[32-1:0]);
      A_FRAME_SIZE: rd_data = 32'(frame_size_q[32-1:0]);
      A_THRESH: rd_data = 32'(thresh_q[8-1:0]);
      A_WIN_X: rd_data = 32'(win_x_q[32-1:0]);
      A_WIN_Y: rd_data = 32'(win_y_q[32-1:0]);
      A_FRAMES: rd_data = 32'(frames_i);
      A_COUNT: rd_data = 32'(count_i);
      A_BOX_X: rd_data = 32'(box_x_i);
      A_BOX_Y: rd_data = 32'(box_y_i);
      A_SUM_X: rd_data = 32'(sum_x_i);
      A_SUM_Y: rd_data = 32'(sum_y_i);
      A_STATUS: rd_data = 32'(status_i);
      A_RUN: rd_data = 32'(run_q[32-1:0]);
      A_Y_RANGE: rd_data = 32'(y_range_q[16-1:0]);
      A_CB_RANGE: rd_data = 32'(cb_range_q[16-1:0]);
      A_CR_RANGE: rd_data = 32'(cr_range_q[16-1:0]);
      A_SAT_MIN: rd_data = 32'(sat_min_q[8-1:0]);
      A_BLOB_CFG: rd_data = 32'(blob_cfg_q[32-1:0]);
      A_RUN_B: rd_data = 32'(run_b_q[32-1:0]);
      default: begin
        for (int i = 0; i < 28; i++)
          if (rd_addr_q == A_SCRATCH + 9'(4 * i)) rd_data = 32'(scratch_q[i][32-1:0]);
        for (int i = 0; i < 8; i++)
          if (rd_addr_q == A_BLOB_X + 9'(4 * i)) rd_data = 32'(blob_x_i[i*(32) +: 32]);
        for (int i = 0; i < 8; i++)
          if (rd_addr_q == A_BLOB_Y + 9'(4 * i)) rd_data = 32'(blob_y_i[i*(32) +: 32]);
        for (int i = 0; i < 8; i++)
          if (rd_addr_q == A_BLOB_N + 9'(4 * i)) rd_data = 32'(blob_n_i[i*(32) +: 32]);
        for (int i = 0; i < 32; i++)
          if (rd_addr_q == A_SKIN_LUT + 9'(4 * i)) rd_data = 32'(skin_lut_q[i][32-1:0]);
      end
    endcase
  end
endmodule
